package io.github.diodeme.ji.testkit;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;

/** Temporary workspace with canonical boundary checks and deterministic cleanup. */
public final class TemporaryWorkspace implements AutoCloseable {
    private final Path root;

    private TemporaryWorkspace(Path root) {
        this.root = root.toAbsolutePath().normalize();
    }

    public static TemporaryWorkspace create() throws IOException {
        return new TemporaryWorkspace(Files.createTempDirectory("ji-test-workspace-"));
    }

    public Path root() {
        return root;
    }

    public Path resolve(String relativePath) {
        Path resolved = root.resolve(relativePath).normalize();
        if (!resolved.startsWith(root)) {
            throw new IllegalArgumentException("path escapes temporary workspace");
        }
        return resolved;
    }

    @Override
    public void close() throws IOException {
        if (!Files.exists(root)) {
            return;
        }
        try (var paths = Files.walk(root)) {
            for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
                Files.deleteIfExists(path);
            }
        }
    }
}
